const result = context.workflow['call_login'].result;
const token = result && result.token;
const user = result && result.user;
const rememberMe = !!variables['4714609d-2a6f-40e0-996a-373bb0effca6'];

if (token && user) {
  const store = rememberMe ? localStorage : sessionStorage;
  const other = rememberMe ? sessionStorage : localStorage;

  store.setItem('authToken', token);
  store.setItem('userId', String(user.id));
  store.setItem('userRole', user.role);
  store.setItem('userName', user.name || '');

  other.removeItem('authToken');
  other.removeItem('userId');
  other.removeItem('userRole');
  other.removeItem('userName');

  if (rememberMe) {
    localStorage.setItem('rememberedEmail', user.email);
  }

  localStorage.setItem('pendingVerifyEmail', user.email);
} else {
  console.log('Register/login response missing token/user', result);
}

